/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Sym, pow, pprintNodes, pprintUseUnicode, printTree } from '../../src';
import { text } from '../sympy-str';

describe("doctests of sympy.printing.tree", () => {
  it("print_tree(y**x)", () => {
    const y = new Sym('y', { even: true });
    const x = new Sym('x', { odd: true });
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(printTree(pow(y, x), {}))).toBe('Pow: y**x\n+-Symbol: y\n| algebraic: True\n| commutative: True\n| complex: True\n| even: True\n| extended_real: True\n| finite: True\n| hermitian: True\n| imaginary: False\n| infinite: False\n| integer: True\n| irrational: False\n| noninteger: False\n| odd: False\n| rational: True\n| real: True\n| transcendental: False\n+-Symbol: x\n  algebraic: True\n  commutative: True\n  complex: True\n  even: False\n  extended_nonzero: True\n  extended_real: True\n  finite: True\n  hermitian: True\n  imaginary: False\n  infinite: False\n  integer: True\n  irrational: False\n  noninteger: False\n  nonzero: True\n  odd: True\n  rational: True\n  real: True\n  transcendental: False\n  zero: False');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("print_tree(y**x, assumptions=False)", () => {
    const y = new Sym('y', { even: true });
    const x = new Sym('x', { odd: true });
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(printTree(pow(y, x), { assumptions: false }))).toBe('Pow: y**x\n+-Symbol: y\n+-Symbol: x');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("print(pprint_nodes([\"a\", \"b1\\nb2\", \"c\"]))", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(pprintNodes(['a', 'b1\nb2', 'c']))).toBe('+-a\n+-b1\n| b2\n+-c');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

